import { MakeLogicType, actions, connect, kea, listeners, path } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { urls } from 'scenes/urls'

import { newCanvasDialogLogic } from 'products/canvas/frontend/newCanvas/newCanvasDialogLogic'

import { ViewType } from './viewsUtils'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface newViewLogicActions {
    openNewCanvasDialog: (spaceId?: string | null) => void // newCanvasDialogLogic
    pickNewViewType: (type: ViewType) => {
        type: ViewType
    }
}

export type newViewLogicType = MakeLogicType<{}, newViewLogicActions>

/** Hands a "New view" pick to the flow that creates that type. */
export const newViewLogic = kea<newViewLogicType>([
    path(['scenes', 'views', 'newViewLogic']),
    connect(() => ({ actions: [newCanvasDialogLogic, ['openNewCanvasDialog']] })),
    actions({
        pickNewViewType: (type: ViewType) => ({ type }),
    }),
    listeners(({ actions }) => ({
        pickNewViewType: ({ type }) => {
            // pinned: analytics event name and property. Renaming them breaks dashboards.
            posthog.capture('views new picked', { type })
            if (type === 'canvas') {
                actions.openNewCanvasDialog()
            } else if (type === 'notebook') {
                router.actions.push(urls.notebook('new'))
            } else {
                // The dashboards page opens its new-dashboard dialog from this hash. Some scenes already host
                // that dialog, so a second host in the shell would open it twice on those pages.
                router.actions.push(`${urls.dashboards()}#newDashboard=modal`)
            }
        },
    })),
])
